    1 use std::hash::{BuildHasher, Hash, Hasher};
    2 use std::path::{Path, PathBuf};
    3 use std::process::Command;
    4 
    5 /// Inputs that can change either peer's executable behavior. Documentation and
    6 /// other repository bookkeeping deliberately do not churn the wire build ID.
    7 const BUILD_INPUTS: &[&str] = &["Cargo.toml", "Cargo.lock", "crates"];
    8 
    9 fn run_git(manifest_dir: &Path, args: &[&str]) -> Option<Vec<u8>> {
   10     let output = Command::new("git")
   11         .args(args)
   12         .current_dir(manifest_dir)
   13         .output()
   14         .ok()?;
   15     output.status.success().then_some(output.stdout)
   16 }
   17 
   18 fn run_git_string(manifest_dir: &Path, args: &[&str]) -> Option<String> {
   19     run_git(manifest_dir, args).map(|bytes| String::from_utf8_lossy(&bytes).trim().to_string())
   20 }
   21 
   22 fn run_scoped_git(manifest_dir: &Path, args: &[&str]) -> Option<Vec<u8>> {
   23     let mut command = Command::new("git");
   24     command.args(args).arg("--");
   25     for input in BUILD_INPUTS {
   26         command.arg(format!(":(top){input}"));
   27     }
   28     let output = command.current_dir(manifest_dir).output().ok()?;
   29     output.status.success().then_some(output.stdout)
   30 }
   31 
   32 fn workspace_root(manifest_dir: &Path, emit_rerun: bool) -> PathBuf {
   33     if emit_rerun {
   34         if let Some(git_dir) = run_git_string(manifest_dir, &["rev-parse", "--absolute-git-dir"]) {
   35             println!("cargo:rerun-if-changed={git_dir}/HEAD");
   36             println!("cargo:rerun-if-changed={git_dir}/refs");
   37             println!("cargo:rerun-if-changed={git_dir}/index");
   38         }
   39     }
   40     let root = run_git_string(manifest_dir, &["rev-parse", "--show-toplevel"])
   41         .map(PathBuf::from)
   42         .or_else(|| {
   43             let candidate = manifest_dir.parent()?.parent()?;
   44             (candidate.join("Cargo.toml").is_file() && candidate.join("crates").is_dir())
   45                 .then(|| candidate.to_path_buf())
   46         })
   47         .unwrap_or_else(|| manifest_dir.to_path_buf());
   48     if emit_rerun {
   49         for input in BUILD_INPUTS {
   50             let path = root.join(input);
   51             println!("cargo:rerun-if-changed={}", path.display());
   52         }
   53     }
   54     root
   55 }
   56 
   57 fn hash_untracked_contents(root: &Path, porcelain: &[u8], hasher: &mut impl Hasher) {
   58     for entry in porcelain.split(|byte| *byte == 0) {
   59         let Some(path_bytes) = entry.strip_prefix(b"?? ") else {
   60             continue;
   61         };
   62         path_bytes.hash(hasher);
   63         let path = root.join(String::from_utf8_lossy(path_bytes).as_ref());
   64         match std::fs::read(path) {
   65             Ok(contents) => contents.hash(hasher),
   66             Err(error) => {
   67                 // A concurrent disappearance or unreadable build input must
   68                 // not collapse onto the identity of a readable file.
   69                 error.kind().hash(hasher);
   70             }
   71         }
   72     }
   73 }
   74 
   75 fn unknown_build_suffix() -> String {
   76     // Independent compilations must never false-match when their source
   77     // identity cannot be established. One built binary still matches itself.
   78     let nonce = std::collections::hash_map::RandomState::new()
   79         .build_hasher()
   80         .finish();
   81     format!("unknown.{nonce:016x}")
   82 }
