  126 /// One failed file of a run's account, by its identity — its text, and its
  127 /// bytes when its name is not text — with the reason the report kept for it,
  128 /// when it kept one, and whether its failure left this run's copy
  129 /// (cr-ecm35-3). One list, from [`RunTotals::failed_files`], for the log and
  130 /// the saved record alike: each joined its failures to its paths by the
  131 /// text alone, and two files of one text, the reason cap falling between
  132 /// them, were named once — or the second without its bytes.
  133 #[derive(Clone, Debug, PartialEq, Eq)]
  134 pub struct FailedFile {
  135     pub path: String,
  136     pub raw: Option<Vec<u8>>,
  137     pub reason: Option<String>,
  138     /// Whether its failure left this run's copy — `None` where the account
  139     /// does not say (cr-ecm35-5): a file past the reason cap missing from a
  140     /// left-in-place list that was cut short.
  141     pub left_in_place: Option<bool>,
