  144 impl RunTotals {
  145     /// Every failed file the account names, each once: the failures the
  146     /// report kept, then each failed path none of them is. A path is one of
  147     /// them by its identity when the account carries the paths' bytes, and
  148     /// by its text when it carries none (a peer that sent none).
  149     pub fn failed_files(&self) -> Vec<FailedFile> {
  150         let carried = self.failed_paths_raw.iter().any(|bytes| !bytes.is_empty());
  151         let left = |path: &str, raw: Option<&[u8]>| match raw {
  152             Some(bytes) => self.left_in_place_raw.iter().any(|left| left == bytes),
  153             None => self.left_in_place.iter().any(|left| left == path),
  154         };
  155         let mut files: Vec<FailedFile> = Vec::new();
  156         for failure in &self.failures {
  157             let raw = failure.raw_relative_path.clone();
  158             if files
  159                 .iter()
  160                 .any(|file| file.path == failure.relative_path && file.raw == raw)
  161             {
  162                 continue;
  163             }
  164             // A failure the report kept says it itself (contract 30).
  165             files.push(FailedFile {
  166                 left_in_place: Some(
  167                     failure.left_in_place || left(&failure.relative_path, raw.as_deref()),
  168                 ),
  169                 path: failure.relative_path.clone(),
  170                 raw,
  171                 reason: Some(failure.reason.clone()),
  172             });
  173         }
  174         for (index, path) in self.failed_paths.iter().enumerate() {
  175             let raw = self
  176                 .failed_paths_raw
  177                 .get(index)
  178                 .filter(|bytes| !bytes.is_empty())
  179                 .cloned();
  180             let named = files
  181                 .iter()
  182                 .any(|file| &file.path == path && (!carried || file.raw == raw));
  183             if named {
  184                 continue;
  185             }
  186             // cr-ecm35-5: one past the cap is told by the lists alone — and
  187             // missing from a list cut short, it is not known.
  188             let left_in_place = if left(path, raw.as_deref()) {
  189                 Some(true)
  190             } else if self.left_in_place_truncated {
  191                 None
  192             } else {
  193                 Some(false)
  194             };
  195             files.push(FailedFile {
  196                 left_in_place,
  197                 path: path.clone(),
  198                 raw,
  199                 reason: None,
  200             });
  201         }
  202         files
  203     }
  204 }
