  345 /// A relative `target` is taken against the current directory, as the OS
  346 /// will take it. Before af-4 a relative destination root never reached
  347 /// this check at all: `canonical_dest_root` failed on it, the sink kept
  348 /// no canonical root, and containment was silently skipped; now that the
  349 /// root is captured, the target has to resolve the same way.
  350 pub fn verify_contained(canonical_module_root: &Path, target: &Path) -> Result<()> {
  351     let mut probe: PathBuf = if target.is_absolute() {
  352         target.to_path_buf()
  353     } else {
  354         std::env::current_dir()
  355             .with_context(|| format!("resolve current_dir for '{}'", target.display()))?
  356             .join(target)
  357     };
  358     let canonical_ancestor = loop {
  359         match std::fs::canonicalize(&probe) {
  360             Ok(c) => break c,
  361             // `NotADirectory` means a component partway down the path is a
  362             // regular file, so the target does not exist — exactly what
  363             // `NotFound` means for this walk, and NOT evidence of an escape.
  364             // Unix reports ENOTDIR here where Windows reports not-found, and
  365             // treating that difference as a containment violation made a
  366             // per-file mkdir failure session-FATAL on Unix only: a tar-shard
  367             // member whose parent is an existing file aborted the whole
  368             // shard instead of being contained (pfc-3's promise, and the
  369             // exact shape of the audit-17 field failure).
  370             //
  371             // Escape detection is unaffected. The loop still stops at the
  372             // deepest EXISTING ancestor and still requires it to canonicalize
  373             // under the root, so a symlinked component pointing outside is
  374             // caught when that component itself is canonicalized.
  375             Err(e)
  376                 if matches!(
  377                     e.kind(),
  378                     std::io::ErrorKind::NotFound | std::io::ErrorKind::NotADirectory
  379                 ) =>
  380             {
  381                 if matches!(probe.components().next_back(), Some(Component::ParentDir)) {
  382                     bail!(
  383                         "path '{}' has a '..' component beyond its deepest existing \
  384                          ancestor; it cannot be resolved for containment",
  385                         target.display()
  386                     );
  387                 }
  388                 if !probe.pop() {
  389                     bail!(
  390                         "path '{}' has no canonicalizable ancestor (root '{}' missing?)",
  391                         target.display(),
  392                         canonical_module_root.display()
  393                     );
  394                 }
  395             }
  396             Err(e) => {
  397                 bail!(
  398                     "canonicalize '{}' for containment check: {}",
  399                     probe.display(),
  400                     e
  401                 );
  402             }
  403         }
  404     };
  405     if !canonical_ancestor.starts_with(canonical_module_root) {
  406         bail!(
  407             "path '{}' resolves to '{}' which escapes module root '{}'",
  408             target.display(),
  409             canonical_ancestor.display(),
  410             canonical_module_root.display()
  411         );
  412     }
