arguments.script:
if ((Get-Location).Path -ne $reviewCopy) { throw 'Unexpected final check directory' }
try {
    [IO.File]::WriteAllText($guardFile,$guardOriginal.Replace($guardLine, 'current.unretried = 0;'))
    cargo test -p blit-transfer --bin blit $guardSelector *> (Join-Path $reviewBuild 'red-isolated.log')
    "guard_red_exit=$LASTEXITCODE"
    Select-String -Path (Join-Path $reviewBuild 'red-isolated.log') -Pattern '^  left:|^ right:|^test result:' | ForEach-Object { $_.Line }
} finally {
    [IO.File]::WriteAllText($guardFile,$guardOriginal)
}
if ((git hash-object $guardFile) -ne (git -C $reviewRepo rev-parse "${reviewPinned}:crates/blit-cli/src/transfers/retry.rs")) { throw 'Final guard source mismatch' }
cargo test -p blit-transfer --bin blit $guardSelector *> (Join-Path $reviewBuild 'green-isolated.log')
"guard_green_exit=$LASTEXITCODE"
Select-String -Path (Join-Path $reviewBuild 'green-isolated.log') -Pattern '^test result:|^test transfers::' | ForEach-Object { $_.Line }
cargo fmt --all -- --check *> (Join-Path $reviewBuild 'fmt-final.log')
"fmt_exit=$LASTEXITCODE"
cargo clippy --workspace --all-targets -- -D warnings *> (Join-Path $reviewBuild 'clippy-final.log')
"clippy_exit=$LASTEXITCODE"
Get-Content (Join-Path $reviewBuild 'clippy-final.log') -Tail 1
cargo test --workspace *> (Join-Path $reviewBuild 'tests-final.log')
"tests_exit=$LASTEXITCODE"
$reviewTests = Get-Content (Join-Path $reviewBuild 'tests-final.log')
$reviewPass = $reviewFail = $reviewIgnore = $reviewBins = 0
foreach ($line in $reviewTests) {
    if ($line -match '^test result: (?:ok|FAILED)\. (\d+) passed; (\d+) failed; (\d+) ignored;') {
        $reviewPass += [int]$matches[1]
        $reviewFail += [int]$matches[2]
        $reviewIgnore += [int]$matches[3]
        $reviewBins++
    }
}
"passed=$reviewPass failed=$reviewFail ignored=$reviewIgnore targets=$reviewBins"
$reviewTests | Select-Object -Last 4
